description:
Write `struct Ring<T, const N: usize>` that keeps the last `N` values pushed into it (older ones are overwritten), backed by an array, with:

- `new()` (for `T: Copy + Default`), `push(&mut self, value: T)`, `len(&self) -> usize` and `is_full(&self) -> bool`;
- `iter(&self)` returning the values from oldest to newest (`impl Iterator<Item = &T> + '_`);
- `impl<T: Copy + Default, const N: usize> FromIterator<T> for Ring<T, N>`, so `(1..=5).collect::<Ring<i32, 3>>()` keeps `[3, 4, 5]`;
- `fn capacity(&self) -> usize` returning `N`.

`Ring<T, 0>` may simply never store anything.

starter.solution.rs:
struct Ring<T, const N: usize> {
    items: [T; N],
    start: usize,
    len: usize,
}

solution.solution.rs:
struct Ring<T, const N: usize> {
    items: [T; N],
    start: usize,
    len: usize,
}

impl<T: Copy + Default, const N: usize> Ring<T, N> {
    fn new() -> Self {
        Ring { items: [T::default(); N], start: 0, len: 0 }
    }

    fn push(&mut self, value: T) {
        if N == 0 {
            return;
        }
        if self.len < N {
            self.items[(self.start + self.len) % N] = value;
            self.len += 1;
        } else {
            self.items[self.start] = value;
            self.start = (self.start + 1) % N;
        }
    }

    fn len(&self) -> usize {
        self.len
    }

    fn is_full(&self) -> bool {
        self.len == N
    }

    fn capacity(&self) -> usize {
        N
    }

    fn iter(&self) -> impl Iterator<Item = &T> + '_ {
        (0..self.len).map(move |i| &self.items[(self.start + i) % N])
    }
}

impl<T: Copy + Default, const N: usize> FromIterator<T> for Ring<T, N> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        let mut r = Ring::new();
        for x in iter {
            r.push(x);
        }
        r
    }
}

unitTests:
fn items<const N: usize>(r: &Ring<i32, N>) -> Vec<i32> { r.iter().copied().collect() }

test("keeps the last N", || {
    let mut r: Ring<i32, 3> = Ring::new();
    for x in 1..=2 { r.push(x); }
    check_eq(items(&r), vec![1, 2]);
    check(!r.is_full());
    for x in 3..=5 { r.push(x); }
    check_eq(items(&r), vec![3, 4, 5]);
    check(r.is_full());
    check_eq((r.len(), r.capacity()), (3, 3));
});

test("collect", || {
    let r: Ring<i32, 3> = (1..=7).collect();
    check_eq(items(&r), vec![5, 6, 7]);
    let small: Ring<i32, 10> = (1..=4).collect();
    check_eq(items(&small), vec![1, 2, 3, 4]);
});

test("other types and sizes", || {
    let r: Ring<char, 2> = "abc".chars().collect();
    check_eq(r.iter().collect::<String>(), "bc");
    let z: Ring<i32, 0> = (1..=3).collect();
    check_eq(z.len(), 0);
});

